"Does {Domain} list a bonus percentage?":{de:"Listet {Domain} einen Bonusprozentsatz?",ru:"Указывает ли {Domain} процент бонуса?",uk:"Чи вказує {Domain} відсоток бонусу?",pl:"Czy {Domain} podaje procent bonusu?",es:"¿{Domain} lista un porcentaje de bono?",pt:"O {Domain} lista uma percentagem de bónus?",fr:"{Domain} ​​affiche-t-il un pourcentage de bonus ?",it:"{Domain} elenca una percentuale bonus?",tr:"{Domain} bonus yüzdesi listeler mi?",nl:"Toont {Domain} een bonuspercentage?"},
